The classical single- and double-layer potentials,
\begin{equation}\label{eq:singleLayer}
    W_\text{single}(z) = \int_\Gamma \sigma(z')\log(z' - z)dz',
\end{equation}
and
\begin{equation}\label{eq:doubleLayer}
    W_\text{double}(z) = \dfrac{1}{2\pi i}\int_\Gamma \dfrac{\mu(z')}{z' - z}dz',
\end{equation}
where $\sigma(z)$ and $\mu(z)$ are referred to as the monopole and dipole densities, respectively, have been used extensively to formulate integral equations~\cite{mikhlin1957integral,atkinson1997numerical,greenbaum1993laplace}.

The density $\sigma(z)$ is often approximated as a weighted combination of Dirac delta functions, as in
\begin{equation}\label{eq:diracDeltas}
    \sigma(z) = \sum_n \sigma_n \delta(z_n-z),
\end{equation}
in which case
\begin{equation}\label{eq:singleLayerApprox}
    W_{\Gamma'}(z) \approx \sum_n \sigma_n\log(z_n - z).
\end{equation}

Assuming that $W(z)$ is also holomorphic for $z \in \Gamma$, it can always be expressed as a series of complex dipole potentials,
\begin{equation}\label{eq:ratFun}
    W(z) = \sum_{n=1}^{\infty} \dfrac{a_n}{z'_n - z}, \quad \forall z \in \Omega,
\end{equation}
where the $z'_n$ are referred to as the poles of $W(z)$.

Our algorithm is based on approximating the complex potential using $N$ poles plus a constant, or equivalently as an $N^\text{th}$ order rational function
\begin{equation}\label{eq:approxWithConst}
    W(z) \approx a_0 + \sum_{n=1}^N \dfrac{a_n}{z'_n - z} = \dfrac{P_N(z)}{Q_N(z)}
\end{equation}
where $P_N$ and $Q_N$ are complex-coefficient polynomials of degree $N$.

To determine $a_0, a_1, \ldots, a_N$, or equivalently, the coefficients of $P_N(z)$, we start with an initial guess for the poles, and associate a complex basis function with each pole,
\begin{equation}\label{eq:psiOfs}
    \phi^{\mathrm{C}}_n(z) = \dfrac{1}{z'_n-z},
\end{equation}
with real and imaginary parts,
\begin{equation}\label{eq:realAndImagPsi}
    \phi^{\mathrm{R}}_n(z) = \mathrm{Re}\left[\phi^{\mathrm{C}}_n(z)\right], \quad \phi^{\mathrm{I}}_n(z) = \mathrm{Im}\left[\phi^{\mathrm{C}}_n(z)\right].
\end{equation}

Defining $U(z) = \mathrm{Re}[W(z)]$ and $V(z) = \mathrm{Im}[W(z)]$, and using \eqref{eq:psiOfs}-\eqref{eq:constant},
\begin{align}\label{eq:approxU}
    U(z) & \approx \widehat{U}(z) = \sum_{n = 0}^{N} a_n^{\mathrm{R}} \phi_n^{\mathrm{R}}(z) - \sum_{n = 1}^{N}a_n^{\mathrm{I}} \phi_n^{\mathrm{I}}(z),
\end{align}
and its harmonic conjugate,
\begin{align}\label{eq:approxV}
    V(z) & \approx \widehat{V}(z) = \sum_{n = 1}^{N} a_n^{\mathrm{R}} \phi_n^{\mathrm{I}}(z) + \sum_{n=1}^N a_n^{\mathrm{I}} \phi_n^{\mathrm{R}}(z),
\end{align}
where the basis function coefficients $a^{\mathrm{R}}_n \equiv \mathrm{Re}(a_n)$ and $a^{\mathrm{I}}_n \equiv \mathrm{Im}(a_n)$ are determined by minimizing an error metric on the boundary $\Gamma$.

More precisely,
\begin{equation}\label{eq:defA}
\mathbf{a} \equiv [a_0^{\mathrm{R}}, a_1^{\mathrm{R}} + i a_1^{\mathrm{I}}, \ldots, a_N^{\mathrm{R}} + i a_N^{\mathrm{I}}]^T
\end{equation}
is determined by solving the minimization problem
\begin{equation}\label{eq:minNormResidues}
        \min_{\mathbf{a}} \left|\left|\widehat{U} - f\right|\right|_\Gamma \equiv   \min_{\mathbf{a}}  \left< \widehat{U}-f, \widehat{U}-f\right>_\Gamma^{\frac{1}{2}},
\end{equation}
where the norm, $||\cdot||_\Gamma$, is induced by a Hermitian inner-product, $\left<\cdot, \cdot\right>_\Gamma$, the definition of which is deferred to Section~\ref{sec:innerProd}.

\begin{equation}\label{eq:defA}
\mathbf{a} \equiv [a_0^{\mathrm{R}}, a_1^{\mathrm{R}} + i a_1^{\mathrm{I}}, \ldots, a_N^{\mathrm{R}} + i a_N^{\mathrm{I}}]^T
\end{equation}

The minimization in~\eqref{eq:minNormResidues} is equivalent to requiring that the residual, $f-\widehat{U}$, be orthogonal to the span of the basis functions, or equivalently,
\begin{subequations}\label{eq:Galerkin}
\begin{align}
    \left<\phi^{\mathrm{R}}_n, f - \widehat{U}\right>_\Gamma & = 0, \quad n = 0,1, \ldots, N,\\
    \left<\phi^{\mathrm{I}}_n, f - \widehat{U}\right>_\Gamma & = 0, \quad n = 1, \ldots, N.
\end{align}
\end{subequations}
Expanding the inner products and using~\eqref{eq:approxU} leads to the normal equations,
\begin{equation}\label{eq:normalEquations}
\begin{bmatrix}
    \mathbf{\Phi}^{\mathrm{R}\mathrm{R}} & \mathbf{\Phi}^{\mathrm{R}\mathrm{I}}\\
    \mathbf{\Phi}^{\mathrm{I}\mathrm{R}} & \mathbf{\Phi}^{\mathrm{I}\mathrm{I}}\\
\end{bmatrix}
\begin{bmatrix}
    \mathbf{a}^{\mathrm{R}}\\
    \mathbf{a}^{\mathrm{I}}\\
\end{bmatrix} =
\begin{bmatrix}
    \mathbf{f}_\phi^{\mathrm{R}}\\
    \mathbf{f}_\phi^{\mathrm{I}}\\
\end{bmatrix},
\end{equation}
where $\mathbf{\Phi}^{\alpha \beta}_{mn} = \left<\phi^{\alpha}_m,\phi^{\beta}_n\right>_\Gamma$ and $(\mathbf{f}^{\alpha}_\phi)_m = \left<f, \phi^{\alpha}_m\right>_\Gamma$.

\begin{align}
    \left<\phi^{\mathrm{R}}_n, f - \widehat{U}\right>_\Gamma & = 0, \quad n = 0,1, \ldots, N,\\
    \left<\phi^{\mathrm{I}}_n, f - \widehat{U}\right>_\Gamma & = 0, \quad n = 1, \ldots, N.
\end{align}

The minimization problem is then
\begin{equation}\label{eq:minProbIRF}
    \min_{P, Q} \left|\left|\dfrac{P - Q\widehat{W}}{\widehat{Q}}\right|\right|_\Gamma,
\end{equation}
where $P$ and $Q$ are represented with polynomial bases, denoted $p_n$ and $q_n$, $n=0, 1, \ldots, N$, respectively.

In VF, the choice is $p_n(z) \equiv q_n(z) \equiv \ell_n(z)$, where
\begin{equation}\label{eq:Lagrange}
    \ell_n(z) =
    \begin{cases}
    \widehat{Q}(z) & \mbox{if } n=0\\
    \dfrac{\widehat{Q}(z)}{\left(z'_n-z\right)}  & \mbox{if } 1 \le n \le N.
    \end{cases}
\end{equation}

For the $p_n(z)$, we use polynomials orthonormal with respect to the inner-product
\begin{equation}
\left<u,v\right>_{\Gamma P} = \left<\dfrac{u}{\widehat{Q}},\dfrac{v}{\widehat{Q}}\right>_\Gamma,
\end{equation}
and for the $q_n(z)$ we use polynomials orthonormal with respect to the inner product
\begin{equation}
\left<u,v\right>_{\Gamma Q} = \left<\dfrac{\widehat{W}u}{\widehat{Q}},\dfrac{\widehat{W}v}{\widehat{Q}}\right>_\Gamma.
\end{equation}

