Both problems can be formulated as follows: given a set basis functions $\psi_1, \psi_2, \ldots \psi_{N_\psi}$ defined on $\Gamma$, and a function to approximate, $g$, also defined on $\Gamma$, we wish to determine the vector of coefficients $\mathbf{c}$ that solves the norm minimization problem
\begin{equation}\label{eq:continuousLS}
   \min_{\mathbf{c}} \left\|\sum_{n=1}^{N_\psi} c_n\psi_n - g\right\|_\Gamma.
\end{equation}

The unique solution to this problem is given by
\begin{equation}\label{eq:pinv}
    \mathbf{c} = \mathbf{\Psi}^{-1}\mathbf{g_\psi},
\end{equation}
where $\mathbf{\Psi}_{mn} = \left<\psi_m,\psi_n\right>_\Gamma$ and $(\mathbf{g_\psi})_m = \left<g,\psi_m\right>_\Gamma$.

The inner product used in this work is
\begin{equation}\label{eq:ip}
    \left<u,v\right>_\Gamma = \int_0^1 u\left(z(s)\right)v^*\left(z(s)\right)\lambda(s)ds,
\end{equation}
where $\lambda(s)$ denotes a positive weight function, and $z(s)$ is a parametrization of $\Gamma$.

If~\eqref{eq:ip} can be evaluated with a single quadrature rule for all $u$'s and $v$'s occurring in inner-product integrals in $\mathbf{\Psi}$ and $\mathbf{g_\psi}$, it is simpler and more numerically stable not to use~\eqref{eq:pinv} explicitly, but instead to sample $\sqrt{\lambda(s)}g(s)$ and the $\sqrt{\lambda(s)}\psi_n(s)$ at the quadrature nodes, and to set-up an overdetermined linear system for $\mathbf{c}$,
\begin{equation}\label{eq:discreteLS}
\begin{bmatrix}
        \sqrt{\lambda_1}\psi_1(s_1) & \cdots & \sqrt{\lambda_1}\psi_{N_\psi}(s_1)\\
        \vdots & \ddots & \vdots\\
        \sqrt{\lambda_{K_\psi}}\psi_1(s_{K_\psi}) & \cdots & \sqrt{\lambda_{K_\psi}}\psi_{N_\psi}(s_{K_\psi})\\
\end{bmatrix}
\begin{bmatrix}
    c_1\\
    \vdots\\
    c_{N_\psi}\\
\end{bmatrix} \approx
\begin{bmatrix}
    \sqrt{\lambda_1}g(s_1)\\
    \vdots\\
    \sqrt{\lambda_{K_\psi}}g(s_{K_\psi})\\
\end{bmatrix},
\end{equation}
where $s_1, s_2, \ldots, s_{K_\psi}$ are the quadrature nodes and $\lambda_1, \lambda_2, \ldots, \lambda_{K_\psi}$ are the quadrature weights.

Equation~\eqref{eq:discreteLS} may also be written as
\begin{equation}\label{eq:LSLambda}
    \mathbf{\Lambda}^{\frac{1}{2}}\mathbf{\widehat{\Psi}} \mathbf{c} \approx \mathbf{\Lambda}^{\frac{1}{2}}\mathbf{\widehat{g}},
\end{equation}
where
\begin{gather}
    \mathbf{\Lambda}  = \mbox{diag}(\lambda_1, \lambda_2, \ldots, \lambda_{K_\psi}) \nonumber  \\
    \mathbf{\widehat{g}}  = [g(s_1), g(s_2), \ldots, g(s_{K_\psi})]^T  \\
    \mathbf{\widehat{\Psi}}_{mn} = \psi_n(s_m). \nonumber
\end{gather}

The least-squares solution to~\eqref{eq:LSLambda} is given analytically by
\begin{equation}\label{eq:LSAnalytic}
\mathbf{c} = \left(\mathbf{\widehat{\Psi}}^H \mathbf{\Lambda} \mathbf{\widehat{\Psi}}\right)^{-1}\mathbf{\widehat{\Psi}}^H \mathbf{\Lambda\widehat{g}},
\end{equation}
where superscript $H$ denotes Hermitian transpose.

